    ...existingRow.value,
    latestUserMessageAt,
    pendingApprovalCount,
    pendingUserInputCount,
    hasActionableProposedPlan: hasActionableProposedPlan ? 1 : 0,
    cumulativeCostUsd,
    toolUses: contextMetrics.toolUses,
