      return { kind: "route", threadId: input.mapping.threadId };
    }
    // Unmapped thread. Only a mention re-engages (seeded with history).
    if (input.mentionsBot) {
      return { kind: "spawn", seedHistory: true };
    }
    return { kind: "ignore", reason: "reply in an unmapped thread without a mention" };
  }

  // Top-level message.
  if (input.surface === "dm") {
    return { kind: "spawn", seedHistory: false };
  }
  // Channel top-level: only a mention spawns (avoids one agent per message).
  if (input.mentionsBot) {
    return { kind: "spawn", seedHistory: false };
  }
  return { kind: "ignore", reason: "channel message without a mention" };
}

